            if key and key in data["cells"]:
                cell = data["cells"][key]
                heatmap_rf[model][strat] = cell["acc_4class"]["random_forest"]
                heatmap_lr[model][strat] = cell["acc_4class"]["logistic_regression"]
            else:
                heatmap_rf[model][strat] = None
                heatmap_lr[model][strat] = None

    valid_rf = [v for m in heatmap_rf.values() for v in m.values() if v is not None]
    return {
        "random_forest": heatmap_rf,
        "logistic_regression": heatmap_lr,
        "summary": {
            "mean_rf_acc": round(np.mean(valid_rf), 4),
            "std_rf_acc": round(np.std(valid_rf), 4),
            "min_rf_acc": round(min(valid_rf), 4),
            "max_rf_acc": round(max(valid_rf), 4),
            "n_cells": len(valid_rf),
            "best_cell": max(data["cells"].items(),
                            key=lambda x: x[1]["acc_4class"]["random_forest"])[0],
            "worst_cell": min(data["cells"].items(),
                             key=lambda x: x[1]["acc_4class"]["random_forest"])[0],
        }
    }


def cross_strategy_monotonicity(data):
    models = data["grid"]["models"]
    strategies = data["grid"]["strategies"]
    cell_keys = data["grid"]["cell_keys"]

    results = {}
    for model in models:
        model_cells = {}
        for strat in strategies:
            key = cell_keys[model].get(strat)
            if key and key in data["cells"]:
                model_cells[strat] = data["cells"][key]

        if len(model_cells) < 2:
            continue

        strat_accs = {s: c["acc_4class"]["random_forest"] for s, c in model_cells.items()}
        strat_mean_auc = {}
        for s, c in model_cells.items():
            aucs = list(c["auc"]["random_forest"].values())
            strat_mean_auc[s] = round(np.mean(aucs), 4)

        hardest_pair_auc = {}
        for s, c in model_cells.items():
            hardest_pair_auc[s] = c["auc"]["random_forest"]["depth2_vs_depth3"]

        results[model] = {
            "acc_by_strategy": strat_accs,
            "mean_auc_by_strategy": strat_mean_auc,
            "d2d3_auc_by_strategy": hardest_pair_auc,
            "n_strategies": len(model_cells),
            "acc_range": round(max(strat_accs.values()) - min(strat_accs.values()), 4),
        }

    return results


def cross_model_rank_correlation(data):
    strategies = data["grid"]["strategies"]
    cell_keys = data["grid"]["cell_keys"]
    models = data["grid"]["models"]

    features = list(data["cells"][list(data["cells"].keys())[0]]["feature_importance"].keys())

    results = {}
    for strat in strategies:
        strat_cells = {}
        for model in models:
            key = cell_keys[model].get(strat)
            if key and key in data["cells"]:
                strat_cells[model] = data["cells"][key]

        if len(strat_cells) < 2:
            results[strat] = {"status": "insufficient_data", "n_models": len(strat_cells)}
            continue

        model_names = list(strat_cells.keys())
        pairwise_rho = {}
        rhos = []
        for m1, m2 in combinations(model_names, 2):
            ranks1 = [strat_cells[m1]["feature_importance"].get(f, 0) for f in features]
            ranks2 = [strat_cells[m2]["feature_importance"].get(f, 0) for f in features]
            rho, pval = stats.spearmanr(ranks1, ranks2)
            pairwise_rho[f"{m1}_vs_{m2}"] = {"rho": round(rho, 4), "p_value": round(pval, 6)}
            rhos.append(rho)

        results[strat] = {
            "pairwise": pairwise_rho,
            "mean_rho": round(np.mean(rhos), 4),
            "n_models": len(strat_cells),
        }

    return results


def compute_edd(data, threshold=0.80):
    """Compute EDD at a given threshold for all cells."""
    per_cell = {}
    models = data["grid"]["models"]
    strategies = data["grid"]["strategies"]
    cell_keys = data["grid"]["cell_keys"]

    consecutive_pairs = [
        ("depth0_vs_depth1", 0, 1),
        ("depth1_vs_depth2", 1, 2),
        ("depth2_vs_depth3", 2, 3),
    ]

    for cell_name, cell in data["cells"].items():
        aucs = cell["auc"]["random_forest"]
        consecutive_aucs = {}
        edd = None
        for pair_key, d_lo, d_hi in consecutive_pairs:
            auc_val = aucs[pair_key]
            consecutive_aucs[f"d{d_lo}v{d_hi}"] = round(auc_val, 4)
            if edd is None and auc_val < threshold:
                edd = d_lo
        if edd is None:
            edd = 3  # all pairs above threshold

        per_cell[cell_name] = {
            "edd": edd,
            "consecutive_aucs": consecutive_aucs,
            "threshold": threshold,
        }

    # Build matrix
    matrix = {}
    for model in models:
        matrix[model] = {}
        for strat in strategies:
            key = cell_keys[model].get(strat)
            if key and key in per_cell:
                matrix[model][strat] = per_cell[key]["edd"]
            else:
                matrix[model][strat] = None

    return {"per_cell": per_cell, "matrix": matrix, "threshold": threshold}


def compute_edd_sensitivity(data, thresholds):
    """EDD sensitivity across multiple thresholds."""
    results = {}
    for th in thresholds:
        edd_result = compute_edd(data, threshold=th)
        results[str(th)] = {
            "threshold": th,
            "matrix": edd_result["matrix"],
            "per_cell": {}
        }
        for cell_name, cell_edd in edd_result["per_cell"].items():
            results[str(th)]["per_cell"][cell_name] = {
                "edd": cell_edd["edd"],
                "consecutive_aucs": cell_edd["consecutive_aucs"],
            }

    # Summary: for each cell, show EDD at each threshold
    cell_summary = {}
    for cell_name in data["cells"]:
        cell_summary[cell_name] = {
            "model": data["cells"][cell_name]["model"],
            "strategy": data["cells"][cell_name]["strategy"],
            "edd_by_threshold": {},
            "consecutive_aucs": {},
        }
        for th in thresholds:
            th_key = str(th)
            cell_summary[cell_name]["edd_by_threshold"][th_key] = results[th_key]["per_cell"][cell_name]["edd"]
            cell_summary[cell_name]["consecutive_aucs"] = results[th_key]["per_cell"][cell_name]["consecutive_aucs"]

    # Matrix summary per threshold
    matrix_summary = {}
    for th in thresholds:
        matrix_summary[str(th)] = results[str(th)]["matrix"]

    return {
        "thresholds": thresholds,
        "per_cell": cell_summary,
        "matrices": matrix_summary,
        "analysis": _edd_sensitivity_analysis(cell_summary, thresholds),
    }


def _edd_sensitivity_analysis(cell_summary, thresholds):
    """Compute summary statistics for EDD sensitivity."""
    # Mean EDD per threshold
    mean_edd_per_th = {}
    for th in thresholds:
        th_key = str(th)
        edds = [c["edd_by_threshold"][th_key] for c in cell_summary.values()]
        mean_edd_per_th[th_key] = {
            "mean": round(np.mean(edds), 2),
            "std": round(np.std(edds), 2),
            "min": int(min(edds)),
            "max": int(max(edds)),
        }

    # Cells most/least sensitive to threshold
    sensitivity = {}
    for cell_name, cell in cell_summary.items():
        edds = [cell["edd_by_threshold"][str(th)] for th in thresholds]
        sensitivity[cell_name] = {
            "edd_range": int(max(edds) - min(edds)),
            "edds": edds,
        }

    most_sensitive = max(sensitivity.items(), key=lambda x: x[1]["edd_range"])
    least_sensitive = min(sensitivity.items(), key=lambda x: x[1]["edd_range"])

    return {
        "mean_edd_per_threshold": mean_edd_per_th,
        "most_sensitive_cell": {"name": most_sensitive[0], **most_sensitive[1]},
        "least_sensitive_cell": {"name": least_sensitive[0], **least_sensitive[1]},
    }


def cross_cell_jaccard(data, top_k=5):
    cell_tops = {}
    for cell_name, cell in data["cells"].items():
        sorted_feats = sorted(cell["feature_importance"].items(), key=lambda x: -x[1])
        cell_tops[cell_name] = set(f for f, _ in sorted_feats[:top_k])

    cell_names = list(cell_tops.keys())
    pairwise = {}
    jaccards = []
    same_model = {}
    same_strategy = {}

    for c1, c2 in combinations(cell_names, 2):
        s1_set = cell_tops[c1]
        s2_set = cell_tops[c2]
        j = len(s1_set & s2_set) / len(s1_set | s2_set)
        j = round(j, 4)
        pairwise[f"{c1}_vs_{c2}"] = j
        jaccards.append(j)

        m1 = data["cells"][c1]["model"]
        m2 = data["cells"][c2]["model"]
        s1 = data["cells"][c1]["strategy"]
        s2 = data["cells"][c2]["strategy"]

        if m1 == m2:
            same_model.setdefault(m1, []).append(j)
        if s1 == s2:
            same_strategy.setdefault(s1, []).append(j)

    return {
        "pairwise": pairwise,
        "mean_jaccard": round(np.mean(jaccards), 4),
        "std_jaccard": round(np.std(jaccards), 4),
        "same_model_mean": {k: round(np.mean(v), 4) for k, v in same_model.items()},
        "same_strategy_mean": {k: round(np.mean(v), 4) for k, v in same_strategy.items()},
        "top_k": top_k,
    }


def universal_feature_ranking(data):
    all_importances = {}
    for cell_name, cell in data["cells"].items():
        for feat, imp in cell["feature_importance"].items():
            all_importances.setdefault(feat, []).append(imp)

    mean_importance = {f: round(np.mean(v), 4) for f, v in all_importances.items()}
    std_importance = {f: round(np.std(v), 4) for f, v in all_importances.items()}

    ranked = sorted(mean_importance.items(), key=lambda x: -x[1])
    return {
        "mean_importance": dict(ranked),
        "std_importance": std_importance,
        "top5_universal": [f for f, _ in ranked[:5]],
        "top5_stable": sorted(ranked[:10], key=lambda x: std_importance[x[0]])[:5],
        "n_cells": len(data["cells"]),
    }


def feature_trajectory_analysis(data):
    """Analyze all 19 features' consecutive pairwise AUC trajectories."""
    features = list(data["cells"][list(data["cells"].keys())[0]]["feature_importance"].keys())

    trajectory = {}
    for cell_name, cell in data["cells"].items():
        aucs_rf = cell["auc"]["random_forest"]
        trajectory[cell_name] = {
            "model": cell["model"],
            "strategy": cell["strategy"],
            "d0v1": aucs_rf["depth0_vs_depth1"],
            "d1v2": aucs_rf["depth1_vs_depth2"],
            "d2v3": aucs_rf["depth2_vs_depth3"],
            "degradation_d0v1_to_d1v2": round(aucs_rf["depth0_vs_depth1"] - aucs_rf["depth1_vs_depth2"], 4),
            "degradation_d1v2_to_d2v3": round(aucs_rf["depth1_vs_depth2"] - aucs_rf["depth2_vs_depth3"], 4),
            "total_degradation": round(aucs_rf["depth0_vs_depth1"] - aucs_rf["depth2_vs_depth3"], 4),
        }

    # Feature importance trajectory per cell
    feature_trajectories = {}
    for feat in features:
        importances = []
        for cell_name, cell in data["cells"].items():
            importances.append({
                "cell": cell_name,
                "model": cell["model"],
                "strategy": cell["strategy"],
                "importance": cell["feature_importance"].get(feat, 0),
            })
        importances.sort(key=lambda x: -x["importance"])
        feature_trajectories[feat] = {
            "mean": round(np.mean([x["importance"] for x in importances]), 4),
            "std": round(np.std([x["importance"] for x in importances]), 4),
            "max_cell": importances[0]["cell"],
            "min_cell": importances[-1]["cell"],
            "cv": round(np.std([x["importance"] for x in importances]) / max(np.mean([x["importance"] for x in importances]), 1e-10), 4),
        }

    return {
        "auc_trajectory": trajectory,
        "feature_trajectories": feature_trajectories,
        "n_features": len(features),
        "features": features,
    }


